#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_xdist;
float4 amzSample_xdist(float2 uv) { return float4(amzt_xdist.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xdist(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_type;
uniform float amzp_threshold;
uniform float amzp_strength;
uniform float amzp_alpha;
uniform float amzp_gradColor;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_scale;
uniform float amzp_iter;
    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
    void amzRender()
    {
            float2 texelSize = 1.0 / getTexSize((screen.zw/1.0));
            float rad = 45.0 * 0.0174533;
            float2 velocity = float2(cos(rad)*(amzp_strength),-sin(rad)*(amzp_strength));
            velocity.x *= screen.zw.y / screen.zw.x;
            float speed = length(velocity / texelSize);
            int nSamples = int(clamp(speed, 1.01, 100.01));
            float4 outColor = amzTexture(1,amzScreenNorm().st);
            for(int i=1; i<nSamples; i++ ) {
                float2 offset = velocity * (float(i) / float(nSamples - 1) - 0.5);
                float2 sampleCoord = amzScreenNorm().st-offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                outColor += amzTexture(1, sampleCoord) * insideTexture;
            }
            float4 d1 = outColor/float(nSamples);
            float2 texelSizeb = 1.0 / getTexSize((screen.zw/1.0));
            float radb = 135.0 * 0.0174533;
            float2 velocityb = float2(cos(radb)*(amzp_strength),-sin(radb)*(amzp_strength));
            velocityb.x *= screen.zw.y / screen.zw.x;
            float speedb = length(velocityb / texelSizeb);
            int nSamplesb = int(clamp(speedb, 1.01, 100.01));
            float4 outColorb = amzTexture(1,amzScreenNorm().st);
            for(int ib=1; ib<nSamplesb; ib++ ) {
                float2 offsetb = velocityb * (float(ib) / float(nSamplesb - 1) - 0.5);
                float2 sampleCoordb = amzScreenNorm().st-offsetb;
                float insideTextureb = step(0.0,sampleCoordb.x) * step(sampleCoordb.x,1.0) * step(0.0,sampleCoordb.y) * step(sampleCoordb.y,1.0);
                outColorb += amzTexture(1, sampleCoordb) * insideTextureb;
            }
            float4 d2 = outColorb/float(nSamplesb);
            float2 texelSizec = 1.0 / getTexSize((screen.zw/1.0));
            float radc = 0.0 * 0.0174533;
            float2 velocityc = float2(cos(radc)*(amzp_strength),-sin(radc)*(amzp_strength));
            velocityc.x *= screen.zw.y / screen.zw.x;
            float speedc = length(velocityc / texelSizec);
            int nSamplesc = int(clamp(speedc, 1.01, 100.01));
            float4 outColorc = amzTexture(1,amzScreenNorm().st);
            for(int ic=1; ic<nSamplesc; ic++ ) {
                float2 offsetc = velocityc * (float(ic) / float(nSamplesc - 1) - 0.5);
                float2 sampleCoordc = amzScreenNorm().st-offsetc;
                float insideTexturec = step(0.0,sampleCoordc.x) * step(sampleCoordc.x,1.0) * step(0.0,sampleCoordc.y) * step(sampleCoordc.y,1.0);
                outColorc += amzTexture(1, sampleCoordc) * insideTexturec;
            }
            float4 d4 = outColorc/float(nSamplesc);
            float2 texelSized = 1.0 / getTexSize((screen.zw/1.0));
            float radd = 90.0 * 0.0174533;
            float2 velocityd = float2(cos(radd)*(amzp_strength),-sin(radd)*(amzp_strength));
            velocityd.x *= screen.zw.y / screen.zw.x;
            float speedd = length(velocityd / texelSized);
            int nSamplesd = int(clamp(speedd, 1.01, 100.01));
            float4 outColord = amzTexture(1,amzScreenNorm().st);
            for(int id=1; id<nSamplesd; id++ ) {
                float2 offsetd = velocityd * (float(id) / float(nSamplesd - 1) - 0.5);
                float2 sampleCoordd = amzScreenNorm().st-offsetd;
                float insideTextured = step(0.0,sampleCoordd.x) * step(sampleCoordd.x,1.0) * step(0.0,sampleCoordd.y) * step(sampleCoordd.y,1.0);
                outColord += amzTexture(1, sampleCoordd) * insideTextured;
            }
            float4 d5 = outColord/float(nSamplesd);
            float4 d3 = max(d1,d2) * amzp_alpha;
            float4 d6 = max(d4,d5) * amzp_alpha;
            float4 d7 = max(d3,d6) * amzp_alpha;
            float4 d8;
            if(int(amzp_type)==0) {d8 = d3;}
            else if(int(amzp_type)==1) {d8 = d6;}
            else if(int(amzp_type)==2) {d8 = d7;}
            float4 oricol = amzTexture(0,amzScreenNorm());
            amzOutput = amzp_strength > 0.0011 ? (oricol+d8) * oricol.a : oricol;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

